-- mod-temucraft-class-tweaks: spells of the class changes (the client has the same rows in Spell.dbc).
-- Made by tools/build_class_change_spells.py.
SET @ClassSpell := 96400;
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN @ClassSpell AND @ClassSpell+5;
DELETE FROM `spell_dbc` WHERE `ID` IN (@ClassSpell, @ClassSpell+1, @ClassSpell+2, @ClassSpell+3, @ClassSpell+4, @ClassSpell+5);

DELETE FROM `spell_bonus_data` WHERE `entry` = @ClassSpell+3;
